						AND p.invoice_code = 'QT'
					GROUP BY p.trans_id
				) q_vt ON q_vt.quotation_id = inv.quotation_id
				WHERE inv.adv_paid > 0
			) all_payments
			GROUP BY inv_id, account_id
		) paid ON paid.inv_id = v.trans_id AND paid.account_id = v.account_id
        WHERE
            g.group_no = 30
			AND v.cancel = 0
			AND v.voucher_type = 'S'
			AND v.drcr_type = 'Dr'
			AND DATE(v.voucher_date) BETWEEN ? AND ?
			 AND v.branch_id IN (1,2,3)
             AND g.customer_id = ? 
        GROUP BY
			v.account_id, g.account_name, v.trans_id, v.voucher_code, v.voucher_date,
			paid.amount_paid, i.po_number, i.po_date
        HAVING
			sum_due_amt > 0.005
        ORDER BY
			v.voucher_date ASC, v.voucher_code ASC;
    
